function update(dt) {
  if (window.__hocPortraitLocked) return; /* freeze game loop while portrait-locked */
  if (countingDown) { updateBgLayers(dt); return; }

setupTouchControls();
setupFullscreenUi();
window.__hocPortraitLocked = false;
applyPortraitLock();
resizeCanvas();
switchScreen('title');
